parameters.jsCode:
try {
  let raw = $input.first().json.candidates[0].content.parts[0].text;

  raw = raw.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();

  const parsed = JSON.parse(raw);

  // Red de seguridad por si el agente no devuelve el array de líneas
  const lineasArray = parsed.facturas || [];

  return [{
    json: {
      cabecera: {
        ...parsed.cabecera
      },
      facturas: lineasArray
    }
  }];
} catch(e) {
  return [{
    json: {
      error: 'JSON malformado: ' + e.message,
      raw_length: $input.first().json.candidates?.[0]?.content?.parts?.[0]?.text?.length || 0
    }
  }];
}

const cabecera = $input.first().json.cabecera;
const lineas = $input.first().json.facturas;

const jsonT2000 = {
  ruta_pdf: $('Loop Over Items').first().json.cdbASAPATH,
  descripcion: $('Loop Over Items').first().json.cdbDescripcion,
  numero: $('Loop Over Items').first().json.cdbNumero,
  cabecera: {
    emisor_cif: cabecera.emisor_cif,
    emisor_nombre: cabecera.emisor_nombre,
    cliente_nombre: cabecera.cliente_nombre,
    cliente_cif: cabecera.cliente_cif,
    importe_total: cabecera.importe_total,
    notas: cabecera.notas
  },
  facturas: lineas.map(linea => ({
    linea: linea.numero_linea,
    numero_factura: linea.numero_factura || "",
    fecha_factura: linea.fecha_factura || "",
    importe: linea.importe || ""
  }))
};

return [{ json: jsonT2000 }];
